WITH agg AS (SELECT p.p_promo_sk, p.p_promo_name, SUM(cs.cs_ext_discount_amt) AS total_discount_given, SUM(cs.cs_net_paid_inc_tax) AS total_paid_inc_tax, AVG(cs.cs_quantity) AS avg_quantity, MAX(t_sale.t_hour) AS latest_sale_hour FROM promotion p JOIN catalog_sales cs ON cs.cs_promo_sk = p.p_promo_sk JOIN time_dim t_sale ON cs.cs_sold_time_sk = t_sale.t_time_sk WHERE p.p_discount_active = 'N' AND cs.cs_quantity > 1 GROUP BY p.p_promo_sk, p.p_promo_name HAVING SUM(cs.cs_ext_discount_amt) > 500) SELECT agg.p_promo_sk, agg.p_promo_name, agg.total_discount_given, agg.total_paid_inc_tax, agg.avg_quantity, agg.latest_sale_hour, DENSE_RANK() OVER (ORDER BY agg.total_discount_given DESC) AS discount_rank FROM agg ORDER BY agg.total_discount_given DESC LIMIT 7
